        {"cruiser", 1, 5},
        {"ferry", 40, 1},
        {"trawler", 0, 1},
        {"sloop", 1200, 0}
    };

    static String outcome(Object[] c) {
        DuesCalculator calc = new DuesCalculator();
        try {
            return String.valueOf(calc.dues((String) c[0], (Integer) c[1], (Integer) c[2]));
        } catch (RuntimeException e) {
