        "1344",
        "106",
        "265",
        "!IllegalArgumentException: tonnage and days must be positive",
        "!IllegalArgumentException: tonnage and days must be positive",
        "200",
        "3675",
        "10850",
        "20160",
        "8400",
        "5",
        "400",
        "!IllegalArgumentException: tonnage and days must be positive",
        "!IllegalArgumentException: tonnage and days must be positive"
    };

    static int run() {
        int failures = 0;
        for (int i = 0; i < CASES.length; i++) {
            String got = outcome(CASES[i]);
            if (!got.equals(WANT[i])) {
                System.out.println("case " + i + ": got " + got + ", want " + WANT[i]);
                failures++;
            }
        }
        return failures;
    }
}

