package harbour;

/** One pricing rule; the calculator picks the rule by name. */
interface VesselClass {
    int cents(int tonnage, int days);
}

start.src/harbour/DuesCalculator.java:
package harbour;

/** Dues in cents for a stay. */
public class DuesCalculator {
    public int dues(String vesselClass, int tonnage, int days) {
        if (tonnage <= 0 || days <= 0) {
            throw new IllegalArgumentException("tonnage and days must be positive");
        }
        int cents;
        if (vesselClass.equals("ferry")) {
            cents = Math.max(400, 6 * tonnage / 5);
        } else if (vesselClass.equals("tug")) {
            cents = 650 + tonnage / 20 + days * 5;
        } else if (vesselClass.equals("cruiser")) {
            cents = tonnage * 5 / 5;
            if (days > 6) {
                cents = cents - cents / 5;
            }
        } else if (vesselClass.equals("tanker")) {
            cents = Math.max(300, 6 * tonnage / 5);
        } else if (vesselClass.equals("sloop")) {
            cents = tonnage * 4 / 3;
            if (days > 6) {
                cents = cents - cents / 10;
            }
        } else if (vesselClass.equals("trawler")) {
            cents = 25 + 3 * tonnage;
        } else if (vesselClass.equals("barge")) {
            cents = tonnage * 8 / 3;
            if (days > 6) {
                cents = cents - cents / 10;
            }
        } else {
            throw new IllegalArgumentException("unknown vessel class: " + vesselClass);
        }
        return cents * days;
    }
}

