KEYWORDS = {"if", "for", "while", "switch", "catch", "synchronized", "try", "else", "do", "return", "new", "match", "loop",
            "select", "func", "function", "sizeof", "throw", "await", "typeof", "super", "this", "with"}


def read(rel):
    with open(os.path.join(ROOT, rel), encoding="utf-8") as f:
        return f.read()


