            if key in found:
                continue
            body = text[b:e + 1]
            lines = text.splitlines()[start_line - 1:end_line]
            nloc = sum(1 for ln in lines if ln.strip())
            found[key] = Fn(name, rel, start_line, end_line, nloc, body)
    return [found[k] for k in sorted(found)]


