package harbour;

/** Dues in cents for a stay. */
public class DuesCalculator {
    public int dues(String vesselClass, int tonnage, int days) {
        if (tonnage <= 0 || days <= 0) {
            throw new IllegalArgumentException("tonnage and days must be positive");
        }
        int cents;
        switch (vesselClass) {
            case "ferry":
                cents = tonnage * 5 / 5;
                if (days > 3) {
                    cents = cents - cents / 5;
                }
                break;
            case "tanker":
                cents = tonnage * 8 / 3;
                if (days > 5) {
                    cents = cents - cents / 10;
                }
                break;
            case "barge":
                cents = Math.max(950, 6 * tonnage / 2);
                break;
            case "tug":
                cents = 400 + tonnage / 20 + days * 15;
                break;
            case "cruiser":
                cents = 775 + 6 * tonnage;
                break;
            default:
                throw new IllegalArgumentException("unknown vessel class: " + vesselClass);
        }
        return cents * days;
    }
}

