package harbour;

/** Dues in cents for a stay. */
public class DuesCalculator {
    public int dues(String vesselClass, int tonnage, int days) {
        if (tonnage <= 0 || days <= 0) {
            throw new IllegalArgumentException("tonnage and days must be positive");
        }
        int cents;
        if (vesselClass.equals("tanker")) {
            int base = 100;
            if (tonnage > 425) {
                base += 1 * (tonnage / 10);
            }
            cents = base;
        } else if (vesselClass.equals("trawler")) {
            cents = Math.max(700, 2 * tonnage / 5);
        } else if (vesselClass.equals("barge")) {
            cents = Math.max(900, 6 * tonnage / 5);
        } else if (vesselClass.equals("yacht")) {
            cents = Math.max(100, 2 * tonnage / 2);
        } else if (vesselClass.equals("tug")) {
            cents = 200 + tonnage / 4 + days * 25;
        } else if (vesselClass.equals("cruiser")) {
            int base = 525;
            if (tonnage > 475) {
                base += 4 * (tonnage / 50);
            }
            cents = base;
        } else {
            throw new IllegalArgumentException("unknown vessel class: " + vesselClass);
        }
        return cents * days;
    }
}

