           "error", "bool", "float64", "fmt"},
    "rust": {"fn", "let", "mut", "if", "else", "for", "while", "loop", "match", "return", "pub", "impl", "struct", "enum", "use", "self",
             "Self", "true", "false", "None", "Some", "Ok", "Err", "as", "in", "ref", "String", "Vec", "Option", "Result", "str", "usize",
