package ticketing;

import java.util.HashMap;
import java.util.Map;

/** Refund in cents for a cancelled ticket. */
public class RefundPolicy {
    private final Map<String, TicketRule> rules = new HashMap<>();

    public RefundPolicy() {
        rules.put("promo", new PromoTicketRule());
        rules.put("group", new GroupTicketRule());
        rules.put("flex", new FlexTicketRule());
        rules.put("standard", new StandardTicketRule());
    }

    public int refund(String kind, int priceCents, int daysBefore) {
        if (priceCents < 0 || daysBefore < 0) {
            throw new IllegalArgumentException("negative input");
        }
        TicketRule rule = rules.get(kind);
        if (rule == null) {
            throw new IllegalArgumentException("no refund rule for " + kind);
        }
        int cents = rule.cents(priceCents, daysBefore);
        return Math.max(0, cents);
    }
}

