package harbour;

import java.util.HashMap;
import java.util.Map;

/** Dues in cents for a stay. */
public class DuesCalculator {
    private final Map<String, VesselClass> rules = new HashMap<>();

    public DuesCalculator() {
        rules.put("yacht", new YachtVesselClass());
        rules.put("tug", new TugVesselClass());
        rules.put("trawler", new TrawlerVesselClass());
        rules.put("ferry", new FerryVesselClass());
        rules.put("cruiser", new CruiserVesselClass());
    }

    public int dues(String vesselClass, int tonnage, int days) {
        if (tonnage <= 0 || days <= 0) {
            throw new IllegalArgumentException("tonnage and days must be positive");
        }
        VesselClass rule = rules.get(vesselClass);
        if (rule == null) {
            throw new IllegalArgumentException("unknown vessel class: " + vesselClass);
        }
        int cents = rule.cents(tonnage, days);
        return cents * days;
    }
}

