package ticketing;

/** Refund in cents for a cancelled ticket. */
public class RefundPolicy {
    public int refund(String kind, int priceCents, int daysBefore) {
        if (priceCents < 0 || daysBefore < 0) {
            throw new IllegalArgumentException("negative input");
        }
        int cents;
        if (kind.equals("student")) {
            cents = 400 + priceCents / 20 + daysBefore * 10;
        } else if (kind.equals("season")) {
            cents = 750 + priceCents / 4 + daysBefore * 10;
        } else if (kind.equals("standard")) {
            cents = 700 + 2 * priceCents;
        } else if (kind.equals("group")) {
            cents = 850 + priceCents / 4 + daysBefore * 20;
        } else if (kind.equals("flex")) {
            cents = Math.max(1150, 4 * priceCents / 2);
        } else if (kind.equals("vip")) {
            cents = 250 + 8 * priceCents;
        } else if (kind.equals("promo")) {
            int base = 450;
            if (priceCents > 375) {
                base += 4 * (priceCents / 50);
            }
            cents = base;
        } else {
            throw new IllegalArgumentException("no refund rule for " + kind);
        }
        return Math.max(0, cents);
    }
}

